// Общее для тестов «<html lang="he" dir="rtl">» (#9c4736, PR #198) и кнопки меню (#2f6eef). Прод, только чтение.
// Адреса категории и объявления не выдумываются: категория — первая /search?category= из /sitemap.xml,
// объявление — первая ссылка /businessdetail?id= из сырого /search (как в ssr-infra.helpers.ts).
import { expect, APIRequestContext, BrowserContext, Page } from '@playwright/test';
import { decodeEntities } from '../ssr-infra/ssr-infra.helpers';

export const LOAD = { timeout: 25_000 };
const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];

/** Неизвестный путь — soft 404 (тот же shell, статус 200). */
export const UNKNOWN_PATH = '/qa-test-404-xyz';

export type PageKey = 'home' | 'search' | 'category' | 'listing' | 'guides' | 'auth' | 'calculator' | 'unknown';

/** Гостевые страницы для проверки dir (тикет: «כיוון הדף כולו»). /guides — без неё: с #359741 гость уходит на главную. */
export const GUEST_PAGES: PageKey[] = ['home', 'search', 'category', 'listing', 'auth', 'calculator', 'unknown'];

/** Страницы только для админа (#359741: /guides видит только admin) — открываются с сессией ../auth/admin.json. */
export const ADMIN_PAGES: PageKey[] = ['guides'];
export const ADMIN_STATE = '../auth/admin.json';

const STATIC: Partial<Record<PageKey, string>> = {
  home: '/',
  search: '/search',
  guides: '/guides',
  auth: '/auth',
  calculator: '/calculator',
  unknown: UNKNOWN_PATH,
};

/** Путь страницы; category и listing — из sitemap.xml и сырого /search. */
export async function pathOf(request: APIRequestContext, key: PageKey): Promise<string> {
  if (STATIC[key]) return STATIC[key]!;
  if (key === 'category') {
    const sitemap = await (await request.get('/sitemap.xml')).text();
    const cat = sitemap.match(/<loc>[^<]*?(\/search\?category=[^<]+)<\/loc>/)?.[1];
    expect(cat, 'в sitemap.xml есть /search?category=').toBeTruthy();
    return decodeEntities(cat!);
  }
  const search = await (await request.get('/search')).text();
  const id = search.match(/href="\/businessdetail\?id=([0-9a-f-]+)/)?.[1];
  expect(id, 'в сыром /search есть ссылка /businessdetail?id=').toBeTruthy();
  return `/businessdetail?id=${id}`;
}

/** Вызывать до первого перехода: не-GET обрываются (кроме продления сессии, если allowTokenRefresh), cookie — «только необходимые». */
export async function prepareReadOnly(context: BrowserContext, opts: { allowTokenRefresh?: boolean } = {}) {
  await context.route('**/*', (route) => {
    const r = route.request();
    const tokenRefresh = opts.allowTokenRefresh && r.method() === 'POST' && /\/auth\/v1\/token/.test(r.url());
    return SAFE_METHODS.includes(r.method()) || tokenRefresh ? route.fallback() : route.abort('blockedbyclient');
  });
  await context.addInitScript(() => {
    try {
      if (!localStorage.getItem('cookie-consent-v2')) {
        localStorage.setItem(
          'cookie-consent-v2',
          JSON.stringify({ essential: true, performance: false, marketing: false, updatedAt: new Date().toISOString() }),
        );
      }
    } catch {}
  });
}

/** Окно PWA «אל תחמיצו אף הזדמנות» — «אולי מאוחר יותר»; cookie — «חיוניים בלבד» (если баннер всё же показан). */
export async function dismissPopups(page: Page) {
  await page.addLocatorHandler(page.getByRole('button', { name: 'אולי מאוחר יותר' }), (b) => b.click());
  await page.addLocatorHandler(page.getByRole('button', { name: 'חיוניים בלבד' }), (b) => b.click());
}

/** Дождаться, что страница отрисована приложением (после гидратации), — без пауз и networkidle. */
export async function waitReady(page: Page, key: PageKey) {
  if (key === 'auth') {
    // На /auth нет шапки и <main> — экран входа (h1 «זירת העסקים…» только на десктопе, «ברוכים הבאים» — на обеих ширинах).
    await expect(page.getByRole('heading', { level: 2, name: 'ברוכים הבאים', exact: true }), '/auth: экран входа').toBeVisible(LOAD);
    return;
  }
  await expect(page.getByRole('banner'), 'шапка сайта').toBeVisible(LOAD);
  const main = page.getByRole('main');
  switch (key) {
    case 'home':
      await expect(page.getByRole('link', { name: 'צפה בכל העסקים' }).first(), 'главная: «צפה בכל העסקים»').toBeVisible(LOAD);
      break;
    case 'search':
    case 'category':
      await expect(main.locator('a[href^="/businessdetail?id="]').first(), 'выдача: карточка объявления').toBeVisible(LOAD);
      break;
    case 'listing':
      await expect(main.getByRole('heading', { level: 1 }), 'объявление: заголовок').toBeVisible(LOAD);
      break;
    case 'guides':
      await expect(page.getByRole('heading', { level: 1, name: 'מדריכי וידאו' }), '/guides: заголовок').toBeVisible(LOAD);
      break;
    case 'calculator':
      await expect(page.locator('#calc-purchasePrice'), '/calculator: форма').toBeVisible(LOAD);
      break;
    case 'unknown':
      await expect(page.getByRole('contentinfo'), 'неизвестный путь: футер shell').toBeAttached(LOAD);
      break;
  }
}

/** dir/lang документа и вычисленное направление body. */
export const docDirection = (page: Page) =>
  page.evaluate(() => ({
    dir: document.documentElement.getAttribute('dir'),
    lang: document.documentElement.getAttribute('lang'),
    body: getComputedStyle(document.body).direction,
  }));

export async function expectRtlDocument(page: Page, where: string) {
  expect(await docDirection(page), `${where}: <html dir="rtl" lang="he">, body direction rtl`).toEqual({
    dir: 'rtl',
    lang: 'he',
    body: 'rtl',
  });
}
